1	/**
2	 * 多签钱包策略引擎。
3	 *
4	 * 在阈值策略、签名收集、重放防护、FIFO 执行队列、策略变更任务与任务取消之上，新增
5	 * “原子批量普通交易”：当前所有者以阈值签名（safe-wallet/tx-batch/v1 域，绑定钱包标识、
6	 * nonce、截止时间与按顺序编码的全部调用）提交一个有序调用列表（1..64 项）。
7	 * 批量任务只入队一个队列任务、只消费一个 nonce；执行时整批成功产生一个 transfer-batch
8	 * 回执（不产生部分执行回执），失败则整批不生效。批量任务沿用同一 FIFO 队列、取消语义与
9	 * 终态幂等；单笔交易 / 策略变更 / 取消签名均不能授权批量交易。
10	 *
11	 * 在此之上新增“普通交易分阶段审批”：createTransactionApproval 登记交易（不消费 nonce、
12	 * 不建任务），addApprovalSignature 逐个收集当前所有者签名（safe-wallet/tx-approval/v1 域，
13	 * 绑定创建时策略版本与完整交易字段），达到创建时确认数后由 submitApprovedTransaction 按
14	 * 既有 safe-wallet/tx/v1 摘要入队并只消费创建时 nonce。审批与直接提交的签名摘要互不通用。
15	 */
16	
17	import {
18	  type Address,
19	  ZERO_ADDRESS,
20	  isZeroAddress,
21	  normalizeAddress,
22	  recoverAddress,
23	} from './crypto.ts';
24	import {
25	  hashCancellation,
26	  hashPolicyChange,
27	  hashTransaction,
28	  hashTransactionApproval,
29	  hashTransactionBatch,
30	  type PolicyChangeRequest,
31	  type TransactionApprovalRequest,
32	  type TransactionBatchRequest,
33	  type TransactionRequest,
34	} from './encoding.ts';
35	import {
36	  ApprovalAlreadySubmittedError,
37	  ApprovalExpiredError,
38	  ApprovalNonceConflictError,
39	  ApprovalNotFoundError,
40	  ApprovalPolicyConflictError,
41	  ApprovalThresholdNotMetError,
42	  DuplicateApprovalSignatureError,
43	  InvalidApprovalSignatureError,
44	  InvalidCancellation,
45	  InvalidPolicyChange,
46	  InvalidTransaction,
47	  InvalidTransactionBatch,
48	  NonceAlreadyUsedError,
49	  RequestExpired,
50	  PolicyConflict,
51	  InvalidQueueStateError,
52	  TaskCancellationConflict,
53	  TaskNotFoundError,
54	} from './errors.ts';
55	import { ExecutionQueue, type QueueTask } from './queue.ts';
56	import { createHash } from 'node:crypto';
57	
58	// ---------- 任务载荷 ----------
59	
60	export type WalletTaskPayload =
61	  | {
62	      kind: 'transaction';
63	      deadline: bigint;
64	      to: Address;
65	      value: bigint;
66	      data: Uint8Array;
67	    }
68	  | {
69	      kind: 'transaction-batch';
70	      deadline: bigint;
71	      /** 有序调用；顺序即执行顺序，执行回执按同一顺序给出 */
72	      calls: BatchCall[];
73	    }
74	  | {
75	      kind: 'policy-change';
76	      deadline: bigint;
77	      /** 提交时绑定的策略版本；执行时必须仍等于当前版本 */
78	      version: bigint;
79	      newOwners: Address[];
80	      newConfirmations: bigint;
81	    };
82	
83	/** 批量任务内的单次调用（规范化后的收款地址、原金额、原始 data 副本） */
84	export interface BatchCall {
85	  to: Address;
86	  value: bigint;
87	  data: Uint8Array;
88	}
89	
90	export type WalletTask = QueueTask<WalletTaskPayload>;
91	
92	export interface PolicyState {
93	  owners: Address[];
94	  confirmations: bigint;
95	  version: bigint;
96	}
97	
98	export interface WalletOptions {
99	  id: string;
100	  owners: Address[];
101	  confirmations: bigint | number;
102	  /** 注入时钟，返回 Unix 秒；默认取系统时间 */
103	  now?: () => bigint;
104	}
105	
106	export interface TransactionSubmission {
107	  nonce: bigint | number;
108	  deadline: bigint | number;
109	  to: string;
110	  value: bigint | number;
111	  data?: Uint8Array;
112	}
113	
114	export interface PolicyChangeSubmission {
115	  version: bigint | number;
116	  nonce: bigint | number;
117	  deadline: bigint | number;
118	  newOwners: string[];
119	  newConfirmations: bigint | number;
120	}
121	
122	export interface CancellationSubmission {
123	  /** 目标任务 id（队列快照中的任务标识） */
124	  taskId: string;
125	  nonce: bigint | number;
126	  deadline: bigint | number;
127	}
128	
129	/** 批量提交中的单次调用（原始输入；地址在校验时规范化） */
130	export interface BatchCallSubmission {
131	  to: string;
132	  value: bigint | number;
133	  /** 必含的调用数据（允许零长度）；必须是 Uint8Array */
134	  data: Uint8Array;
135	}
136	
137	export interface BatchTransactionSubmission {
138	  nonce: bigint | number;
139	  deadline: bigint | number;
140	  /** 有序调用列表：非空且最多 MAX_BATCH_CALLS 项，顺序参与签名且不得改变 */
141	  calls: readonly BatchCallSubmission[];
142	}
143	
144	/** 批量交易调用数量上限（含） */
145	export const MAX_BATCH_CALLS = 64;
146	
147	// ---------- 普通交易分阶段审批 ----------
148	
149	/** 审批生命周期：collecting → ready → submitted；expired / conflicted 为查询派生状态 */
150	export type ApprovalStatus = 'collecting' | 'ready' | 'expired' | 'conflicted' | 'submitted';
151	
152	/** 审批的公开快照（创建 / 加签 / 查询时返回） */
153	export interface TransactionApproval {
154	  /** 审批标识（由创建序号与审批摘要派生，引擎内唯一） */
155	  id: string;
156	  /** 审批签名摘要（hex，safe-wallet/tx-approval/v1 域） */
157	  digest: string;
158	  /** 创建时绑定的策略版本 */
159	  version: bigint;
160	  /** 创建时绑定的确认数（阈值） */
161	  confirmations: bigint;
162	  /** 已收集签名者（按加签顺序，去重） */
163	  signers: Address[];
164	  status: ApprovalStatus;
165	}
166	
167	/** 审批的内部记录：完整交易字段 + 签名收集状态 */
168	interface ApprovalRecord {
169	  id: string;
170	  digest: Buffer;
171	  version: bigint;
172	  confirmations: bigint;
173	  nonce: bigint;
174	  deadline: bigint;
175	  to: Address;
176	  value: bigint;
177	  data: Buffer;
178	  /** 按加签顺序的签名者（与 signatures 的键一一对应） */
179	  signers: Address[];
180	  signatures: Map<Address, Buffer>;
181	  submitted: boolean;
182	}
183	
184	function isNonNegativeInteger(n: bigint, maxBits = 256): boolean {
185	  return n >= 0n && n < 2n ** BigInt(maxBits);
186	}
187	
188	/** 安全标量转换：非法输入（undefined / 字符串等）归一为指定的 Invalid* 错误 */
189	function toBigInt(value: unknown, Invalid: new (msg: string) => Error, field: string): bigint {
190	  if (typeof value === 'bigint') return value;
191	  if (typeof value === 'number' && Number.isSafeInteger(value)) return BigInt(value);
192	  if (typeof value === 'string' && /^\d+$/.test(value.trim())) return BigInt(value.trim());
193	  throw new Invalid(`field "${field}" must be a non-negative integer`);
194	}
195	
196	export class MultiSigWallet {
197	  readonly id: string;
198	  private readonly now: () => bigint;
199	
200	  private owners: Address[];
201	  private readonly ownerSet: Set<Address>;
202	  private confirmations: bigint;
203	  private version: bigint;
204	
205	  /** 下一个期望 nonce（严格递增，顺序提交） */
206	  private nextNonce = 0n;
207	  /** 已消费 nonce（入队即消费；失败终态也不释放） */
208	  private readonly usedNonces = new Set<bigint>();
209	
210	  /** 分阶段审批记录（按创建顺序）；创建不消费 nonce，提交时才消费 */
211	  private readonly approvals = new Map<string, ApprovalRecord>();
212	  private approvalSeq = 0;
213	
214	  readonly queue: ExecutionQueue<WalletTaskPayload>;
215	
216	  constructor(opts: WalletOptions) {
217	    const owners = normalizeOwnerList(opts.owners);
218	    const confirmations = BigInt(opts.confirmations);
219	    if (confirmations <= 0n || confirmations > BigInt(owners.length)) {
220	      throw new InvalidPolicyChange(
221	        `initial confirmations must be within 1..owners (${owners.length}), got ${confirmations}`,
222	      );
223	    }
224	    this.id = opts.id;
225	    this.now = opts.now ?? (() => BigInt(Math.floor(Date.now() / 1000)));
226	    this.owners = owners;
227	    this.ownerSet = new Set(owners);
228	    this.confirmations = confirmations;
229	    this.version = 1n;
230	    this.queue = new ExecutionQueue((task) => this.applyTask(task));
231	  }
232	
233	  // ---------- 只读状态 ----------
234	
235	  get policy(): PolicyState {
236	    return { owners: [...this.owners], confirmations: this.confirmations, version: this.version };
237	  }
238	
239	  get policyVersion(): bigint {
240	    return this.version;
241	  }
242	
243	  get currentOwners(): Address[] {
244	    return [...this.owners];
245	  }
246	
247	  get requiredConfirmations(): bigint {
248	    return this.confirmations;
249	  }
250	
251	  get expectedNonce(): bigint {
252	    return this.nextNonce;
253	  }
254	
255	  isOwner(address: string): boolean {
256	    const a = normalizeAddress(address);
257	    return a !== null && this.ownerSet.has(a);
258	  }
259	
260	  isNonceUsed(nonce: bigint | number): boolean {
261	    return this.usedNonces.has(BigInt(nonce));
262	  }
263	
264	  get tasks(): readonly WalletTask[] {
265	    return this.queue.listTasks();
266	  }
267	
268	  // ---------- 普通交易提交（行为与既有流程一致，载荷不含策略版本） ----------
269	
270	  submitTransaction(sub: TransactionSubmission, signatures: readonly Uint8Array[]): WalletTask {
271	    // 原始值透传，由 submit 统一做安全转换，避免在入口抛出原生 TypeError
272	    return this.submit(
273	      'transaction',
274	      {
275	        nonce: sub.nonce,
276	        deadline: sub.deadline,
277	        to: sub.to,
278	        value: sub.value,
279	        data: sub.data ?? new Uint8Array(),
280	      },
281	      signatures,
282	    );
283	  }
284	
285	  // ---------- 原子批量普通交易提交 ----------
286	
287	  /**
288	   * 提交一个有序调用列表作为单个原子批量任务。
289	   *
290	   * 摘要使用 safe-wallet/tx-batch/v1 域标签，绑定钱包标识、nonce、截止时间与按顺序编码的
291	   * 全部调用：单笔交易 / 策略变更 / 取消签名都不能授权批量交易；任一调用的收款方、金额、
292	   * data 或调用顺序、项数变化都会改变摘要。
293	   *
294	   * 校验顺序与单笔提交一致（任一失败都不建任务、不消费 nonce、不改策略/队列）：
295	   *   1) nonce 复用 → NonceAlreadyUsedError（旧请求重放恒得此异常，即使已过期）
296	   *   2) deadline 早于当前时间 → RequestExpired
297	   *   3) 列表（1..64 项）、收款地址、金额、data、nonce 顺序、阈值签名 → InvalidTransactionBatch
298	   *
299	   * 成功时只入队一个批量任务、只消费本次 nonce 并推进 expectedNonce。
300	   */
301	  submitBatchTransaction(sub: BatchTransactionSubmission, signatures: readonly Uint8Array[]): WalletTask {
302	    return this.submit(
303	      'transaction-batch',
304	      {
305	        nonce: sub.nonce,
306	        deadline: sub.deadline,
307	        calls: sub.calls,
308	      },
309	      signatures,
310	    );
311	  }
312	
313	  // ---------- 策略变更提交 ----------
314	
315	  proposePolicyChange(sub: PolicyChangeSubmission, signatures: readonly Uint8Array[]): WalletTask {
316	    return this.submit(
317	      'policy-change',
318	      {
319	        version: sub.version,
320	        nonce: sub.nonce,
321	        deadline: sub.deadline,
322	        newOwners: sub.newOwners,
323	        newConfirmations: sub.newConfirmations,
324	      },
325	      signatures,
326	    );
327	  }
328	
329	  // ---------- 任务取消 ----------
330	
331	  /**
332	   * 取消一个尚未执行的 queued 任务。
333	   *
334	   * 取消摘要使用 safe-wallet/cancel/v1 域标签，绑定钱包标识、目标任务 digest、nonce 与
335	   * 截止时间：签名无法改绑其他任务、其他钱包或其他时间窗口。
336	   *
337	   * 校验顺序（任一失败都不改变任务、不消费 nonce、不改变策略）：
338	   *   1) 字段非法 → InvalidCancellation
339	   *   2) nonce 复用 → NonceAlreadyUsedError（旧请求重放恒得此异常，即使已过期）
340	   *   3) deadline 早于当前时间 → RequestExpired
341	   *   4) nonce 顺序（须等于 expectedNonce）→ InvalidCancellation
342	   *   5) 目标不存在 → TaskNotFoundError；目标已终态 → TaskCancellationConflict
343	   *   6) 阈值签名（当前所有者、去重后达到当前确认数）→ InvalidCancellation
344	   *
345	   * 成功时目标任务由 queued 进入 cancelled 终态并返回：保留原 payload/digest/nonce，
346	   * 记录取消时间与取消摘要；不执行目标效果，不改变 owners/确认数/策略版本，
347	   * 只消费本次 nonce 并推进 expectedNonce。取消不要求任务在队首，也不调整队列顺序。
348	   */
349	  cancelTask(
350	    taskId: string,
351	    nonce: bigint | number,
352	    deadline: bigint | number,
353	    signatures: readonly Uint8Array[],
354	  ): WalletTask;
355	  cancelTask(sub: CancellationSubmission, signatures: readonly Uint8Array[]): WalletTask;
356	  cancelTask(
357	    a: string | CancellationSubmission,
358	    b: readonly Uint8Array[] | bigint | number,
359	    c?: bigint | number,
360	    d?: readonly Uint8Array[],
361	  ): WalletTask {
362	    const sub: CancellationSubmission =
363	      typeof a === 'string' || a === undefined || a === null
364	        ? { taskId: a as string, nonce: b as bigint | number, deadline: c as bigint | number }
365	        : a;
366	    const signatures: readonly Uint8Array[] =
367	      (typeof a === 'string' || a === undefined || a === null ? d : (b as readonly Uint8Array[])) ??
368	      ([] as readonly Uint8Array[]);
369	
370	    // (1) 字段安全转换（畸形输入只抛 InvalidCancellation）
371	    const nonce = toBigInt(sub.nonce, InvalidCancellation, 'nonce');
372	    if (!isNonNegativeInteger(nonce)) {
373	      throw new InvalidCancellation('nonce must be a non-negative integer');
374	    }
375	    // (2) nonce 复用优先于过期判定
376	    if (this.usedNonces.has(nonce)) throw new NonceAlreadyUsedError(nonce);
377	
378	    const deadline = toBigInt(sub.deadline, InvalidCancellation, 'deadline');
379	    if (!isNonNegativeInteger(deadline)) throw new InvalidCancellation('deadline out of range');
380	    // (3) 截止时间
381	    if (deadline < this.now()) {
382	      throw new RequestExpired(`request deadline ${deadline} already passed`);
383	    }
384	    // (4) nonce 顺序：取消与提交共用同一严格递增序列
385	    if (nonce !== this.nextNonce) {
386	      throw new InvalidCancellation(`expected nonce ${this.nextNonce}, got ${nonce}`);
387	    }
388	
389	    // (5) 目标任务状态
390	    const taskId = sub.taskId;
391	    if (typeof taskId !== 'string' || taskId.length === 0) {
392	      throw new InvalidCancellation('taskId must be a non-empty string');
393	    }
394	    const target = this.queue.getTask(taskId);
395	    if (target === null) throw new TaskNotFoundError(`task not found: ${taskId}`);
396	    if (target.status !== 'queued') {
397	      throw new TaskCancellationConflict(`task ${taskId} is already ${target.status}`);
398	    }
399	
400	    // (6) 阈值签名：摘要绑定钱包标识、目标任务 digest、nonce、deadline
401	    const digest = hashCancellation({
402	      walletId: this.id,
403	      taskDigest: target.digest,
404	      nonce,
405	      deadline,
406	    });
407	    this.verifyThresholdSignatures(digest, signatures, InvalidCancellation);
408	
409	    // 原子生效：目标任务进入 cancelled 终态 + 消费 nonce；策略与队列顺序不变
410	    const cancelled = this.queue.cancel(taskId, this.now(), digest.toString('hex'));
411	    this.usedNonces.add(nonce);
412	    this.nextNonce = nonce + 1n;
413	    return cancelled;
414	  }
