416	  // ---------- 普通交易分阶段审批（签名收集与提交分离；旧入口行为不变） ----------
417	
418	  /**
419	   * 创建一笔普通交易的分阶段审批：只校验并登记，不消费 nonce、不建任务、不改策略。
420	   *
421	   * 审批摘要用 safe-wallet/tx-approval/v1 域，绑定钱包标识、创建时策略版本与完整交易字段
422	   * （data 复制保存），与直接提交的 safe-wallet/tx/v1 摘要互不通用。
423	   *
424	   * 校验顺序与 submitTransaction 一致（失败不产生任何状态变化）：
425	   *   1) nonce 复用 → NonceAlreadyUsedError
426	   *   2) deadline 早于当前时间 → RequestExpired
427	   *   3) 字段非法或 nonce 跳号（须等于 expectedNonce）→ InvalidTransaction
428	   *
429	   * 成功时返回审批快照（标识、摘要、版本、确认数、空签名者列表、collecting 状态）。
430	   */
431	  createTransactionApproval(sub: TransactionSubmission): TransactionApproval {
432	    // (1) nonce 安全转换与复用判定（复用优先于过期，与既有提交一致）
433	    const nonce = toBigInt(sub.nonce, InvalidTransaction, 'nonce');
434	    if (!isNonNegativeInteger(nonce)) throw new InvalidTransaction('nonce must be a non-negative integer');
435	    if (this.usedNonces.has(nonce)) throw new NonceAlreadyUsedError(nonce);
436	
437	    // (2) 截止时间
438	    const deadline = toBigInt(sub.deadline, InvalidTransaction, 'deadline');
439	    if (!isNonNegativeInteger(deadline)) throw new InvalidTransaction('deadline out of range');
440	    if (deadline < this.now()) {
441	      throw new RequestExpired(`request deadline ${deadline} already passed`);
442	    }
443	    // (3) nonce 顺序：创建只登记不消费，但仍须绑定当前期望 nonce（跳号即非法）
444	    if (nonce !== this.nextNonce) {
445	      throw new InvalidTransaction(`expected nonce ${this.nextNonce}, got ${nonce}`);
446	    }
447	
448	    // (4) 交易字段校验与规范化（与直接提交同一套规则）
449	    const to = normalizeAddress(sub.to);
450	    if (to === null || isZeroAddress(to)) throw new InvalidTransaction('invalid or zero recipient address');
451	    const value = toBigInt(sub.value, InvalidTransaction, 'value');
452	    if (!isNonNegativeInteger(value)) throw new InvalidTransaction('value out of range');
453	    const dataField = sub.data;
454	    if (dataField !== undefined && !(dataField instanceof Uint8Array) && !ArrayBuffer.isView(dataField)) {
455	      throw new InvalidTransaction('data must be a byte array');
456	    }
457	    // 复制一份，避免创建后调用方改动同一缓冲区影响审批内容/摘要
458	    const data = Buffer.from((dataField as Uint8Array | undefined) ?? new Uint8Array());
459	
460	    const req: TransactionApprovalRequest = {
461	      walletId: this.id,
462	      version: this.version,
463	      nonce,
464	      deadline,
465	      to,
466	      value,
467	      data,
468	    };
469	    const digest = hashTransactionApproval(req);
470	    const id = createHash('sha256')
471	      .update(`approval:${this.approvalSeq}:${digest.toString('hex')}`)
472	      .digest('hex')
473	      .slice(0, 16);
474	    this.approvalSeq += 1;
475	
476	    const record: ApprovalRecord = {
477	      id,
478	      digest,
479	      version: this.version,
480	      confirmations: this.confirmations,
481	      nonce,
482	      deadline,
483	      to,
484	      value,
485	      data,
486	      signers: [],
487	      signatures: new Map(),
488	      submitted: false,
489	    };
490	    this.approvals.set(id, record);
491	    return this.approvalSnapshot(record);
492	  }
493	
494	  /**
495	   * 给审批追加一个 65 字节签名（每次一个）。
496	   *
497	   * 校验顺序：
498	   *   1) 审批不存在 → ApprovalNotFoundError
499	   *   2) 已提交 → ApprovalAlreadySubmittedError
500	   *   3) 已过期 → ApprovalExpiredError（过期优先于版本冲突）
501	   *   4) 策略版本漂移 → ApprovalPolicyConflictError
502	   *   5) 签名格式 / 与摘要不符 / 签名者非当前所有者 → InvalidApprovalSignatureError
503	   *   6) 同一所有者重复加签 → DuplicateApprovalSignatureError
504	   *
505	   * 达到创建时确认数后状态变为 ready；任一失败都不改变审批内容。
506	   */
507	  addApprovalSignature(approvalId: string, signature: Uint8Array): TransactionApproval {
508	    const record = this.getApprovalRecord(approvalId);
509	    this.assertApprovalActive(record);
510	
511	    if (!(signature instanceof Uint8Array) || signature.length !== 65) {
512	      throw new InvalidApprovalSignatureError('signature must be a 65-byte r||s||v blob');
513	    }
514	    const signer = recoverAddress(record.digest, Uint8Array.from(signature));
515	    if (signer === null) {
516	      throw new InvalidApprovalSignatureError('malformed or non-canonical signature');
517	    }
518	    if (!this.ownerSet.has(signer)) {
519	      throw new InvalidApprovalSignatureError('signature does not match approval or signer is not an owner');
520	    }
521	    if (record.signatures.has(signer)) {
522	      throw new DuplicateApprovalSignatureError(`owner already signed: ${signer}`);
523	    }
524	    record.signers.push(signer);
525	    record.signatures.set(signer, Buffer.from(signature));
526	    return this.approvalSnapshot(record);
527	  }
528	
529	  /** 查询审批快照（状态与按加签顺序的签名者）；未知 id 抛 ApprovalNotFoundError */
530	  getTransactionApproval(approvalId: string): TransactionApproval {
531	    return this.approvalSnapshot(this.getApprovalRecord(approvalId));
532	  }
533	
534	  /**
535	   * 阈值满足后提交审批：按既有 safe-wallet/tx/v1 摘要入队一个普通交易任务，
536	   * 只消费创建时绑定的 nonce 并推进 expectedNonce；队列与既有终态行为不变。
537	   *
538	   * 校验顺序（任一失败都不消费 nonce、不建任务、不改策略）：
539	   *   1) 审批不存在 → ApprovalNotFoundError；已提交 → ApprovalAlreadySubmittedError
540	   *   2) 已过期 → ApprovalExpiredError；版本漂移 → ApprovalPolicyConflictError（过期优先）
541	   *   3) 签名不足创建时确认数 → ApprovalThresholdNotMetError
542	   *   4) nonce 已消费 → NonceAlreadyUsedError；nonce ≠ expectedNonce → ApprovalNonceConflictError
543	   */
544	  submitApprovedTransaction(approvalId: string): WalletTask {
545	    const record = this.getApprovalRecord(approvalId);
546	    this.assertApprovalActive(record);
547	
548	    if (BigInt(record.signers.length) < record.confirmations) {
549	      throw new ApprovalThresholdNotMetError(
550	        `threshold not met: need ${record.confirmations} distinct owners, got ${record.signers.length}`,
551	      );
552	    }
553	    if (this.usedNonces.has(record.nonce)) throw new NonceAlreadyUsedError(record.nonce);
554	    if (record.nonce !== this.nextNonce) {
555	      throw new ApprovalNonceConflictError(`expected nonce ${this.nextNonce}, got ${record.nonce}`);
556	    }
557	
558	    // 按既有普通交易摘要入队（与 submitTransaction 同一域、同一载荷形状）
559	    const req: TransactionRequest = {
560	      walletId: this.id,
561	      nonce: record.nonce,
562	      deadline: record.deadline,
563	      to: record.to,
564	      value: record.value,
565	      data: record.data,
566	    };
567	    const digest = hashTransaction(req);
568	    const payload: WalletTaskPayload = {
569	      kind: 'transaction',
570	      deadline: record.deadline,
571	      to: record.to,
572	      value: record.value,
573	      data: Buffer.from(record.data),
574	    };
575	    let task: WalletTask;
576	    try {
577	      task = this.queue.enqueue({
578	        nonce: record.nonce,
579	        digest: digest.toString('hex'),
580	        payload,
581	        submittedAt: this.now(),
582	      });
583	    } catch (err) {
584	      if (err instanceof InvalidQueueStateError) throw new InvalidTransaction(err.message);
585	      throw err;
586	    }
587	    // 原子生效：入队 + 消费 nonce + 审批进入 submitted 终态
588	    this.usedNonces.add(record.nonce);
589	    this.nextNonce = record.nonce + 1n;
590	    record.submitted = true;
591	    return task;
592	  }
