594	  // ---------- 执行 ----------
595	
596	  executeTask(taskId: string): WalletTask {
597	    return this.queue.execute(taskId, this.now());
598	  }
599	
600	  executeNext(): WalletTask | null {
601	    return this.queue.executeNext(this.now());
602	  }
603	
604	  getTask(taskId: string): WalletTask | null {
605	    return this.queue.getTask(taskId);
