608	  // ============================================================
609	  // 内部实现
610	  // ============================================================
611	
612	  /**
613	   * 统一提交入口。raw 接收未经转换的原始标量（bigint/number/string），
614	   * 所有转换与字段合法性判定都在这里完成，保证只能抛出约定错误类型。
615	   */
616	  private submit(
617	    kind: WalletTaskPayload['kind'],
618	    raw: Record<string, unknown>,
619	    signatures: readonly Uint8Array[],
620	  ): WalletTask {
621	    const Invalid =
622	      kind === 'policy-change'
623	        ? InvalidPolicyChange
624	        : kind === 'transaction-batch'
625	          ? InvalidTransactionBatch
626	          : InvalidTransaction;
627	
628	    // 校验优先级（任一失败都不建任务、不消费 nonce、不改策略）：
629	    //   1) nonce 复用 → 既有重放防护的公开异常（旧请求重放即使已过期也仍报复用）
630	    //   2) 截止时间早于当前时间 → RequestExpired
631	    //   3) 字段 / 版本 / nonce 顺序 / 签名 → 对应 Invalid*
632	    const nonce = toBigInt(raw.nonce, Invalid, 'nonce');
633	    if (!isNonNegativeInteger(nonce)) throw new Invalid('nonce must be a non-negative integer');
634	    if (this.usedNonces.has(nonce)) throw new NonceAlreadyUsedError(nonce);
635	
636	    const deadline = toBigInt(raw.deadline, Invalid, 'deadline');
637	    if (!isNonNegativeInteger(deadline)) throw new Invalid('deadline out of range');
638	    if (deadline < this.now()) {
639	      throw new RequestExpired(`request deadline ${deadline} already passed`);
640	    }
641	    if (nonce !== this.nextNonce) throw new Invalid(`expected nonce ${this.nextNonce}, got ${nonce}`);
642	
643	    // (3) 字段校验 + 规范化
644	    let payload: WalletTaskPayload;
645	    let digest: Buffer;
646	    if (kind === 'transaction') {
647	      const to = normalizeAddress(raw.to as string);
648	      if (to === null || isZeroAddress(to)) throw new Invalid('invalid or zero recipient address');
649	      const value = toBigInt(raw.value, Invalid, 'value');
650	      if (!isNonNegativeInteger(value)) throw new Invalid('value out of range');
651	      const dataField = raw.data;
652	      if (
653	        dataField !== undefined &&
654	        !(dataField instanceof Uint8Array) &&
655	        !ArrayBuffer.isView(dataField)
656	      ) {
657	        throw new Invalid('data must be a byte array');
658	      }
659	      const data = Buffer.from((dataField as Uint8Array | undefined) ?? new Uint8Array());
660	      const req: TransactionRequest = {
661	        walletId: this.id,
662	        nonce,
663	        deadline,
664	        to,
665	        value,
666	        data,
667	      };
668	      digest = hashTransaction(req);
669	      payload = { kind: 'transaction', deadline, to, value, data };
670	    } else if (kind === 'transaction-batch') {
671	      // 有序调用列表：1..64 项；逐项规范化收款地址、金额与 data（顺序保持不变）
672	      const calls = this.normalizeBatchCalls(raw.calls);
673	      const req: TransactionBatchRequest = {
674	        walletId: this.id,
675	        nonce,
676	        deadline,
677	        calls,
678	      };
679	      digest = hashTransactionBatch(req);
680	      payload = { kind: 'transaction-batch', deadline, calls };
681	    } else {
682	      const version = toBigInt(raw.version, InvalidPolicyChange, 'version');
683	      // (3a) 版本必须绑定当前版本（提交时不匹配 → InvalidPolicyChange；执行时漂移 → PolicyConflict）
684	      if (version !== this.version) {
685	        throw new InvalidPolicyChange(
686	          `policy version mismatch: bound ${version}, current ${this.version}`,
687	        );
688	      }
689	      // (3b) 以当前版本为基准验证新策略
690	      const newOwners = normalizeOwnerList(raw.newOwners as string[], InvalidPolicyChange);
691	      const newConfirmations = toBigInt(raw.newConfirmations, InvalidPolicyChange, 'newConfirmations');
692	      if (newConfirmations <= 0n || newConfirmations > BigInt(newOwners.length)) {
693	        throw new InvalidPolicyChange(
694	          `new confirmations must be within 1..new owners (${newOwners.length}), got ${newConfirmations}`,
695	        );
696	      }
697	      const req: PolicyChangeRequest = {
698	        walletId: this.id,
699	        version,
700	        nonce,
701	        deadline,
702	        newOwners,
703	        newConfirmations,
704	      };
705	      digest = hashPolicyChange(req);
706	      payload = { kind: 'policy-change', deadline, version, newOwners, newConfirmations };
707	    }
708	
709	    // (4) 阈值签名：恢复 → 去重 → 必须为当前所有者 → 数量达到当前确认数
710	    this.verifyThresholdSignatures(digest, signatures, Invalid);
711	
712	    // (5) 原子生效（到队列为止）：入队 + 消费 nonce。
713	    //     入队失败（同一摘要重复等）时不消费 nonce。
714	    let task: WalletTask;
715	    try {
716	      task = this.queue.enqueue({
717	        nonce,
718	        digest: digest.toString('hex'),
719	        payload,
720	        submittedAt: this.now(),
721	      });
722	    } catch (err) {
723	      if (err instanceof InvalidQueueStateError) throw new Invalid(err.message);
724	      throw err;
725	    }
726	    this.usedNonces.add(nonce);
727	    this.nextNonce = nonce + 1n;
728	    return task;
729	  }
730	
731	  /**
732	   * 规范化批量调用列表：必须是 1..MAX_BATCH_CALLS 项的数组，每项是对象，
733	   * 收款地址合法且非零、金额为 256 位以内非负整数、data 必须是 Uint8Array。
734	   * 保持输入顺序；任何畸形都归为 InvalidTransactionBatch。
735	   */
736	  private normalizeBatchCalls(rawCalls: unknown): BatchCall[] {
737	    if (!Array.isArray(rawCalls) || rawCalls.length === 0) {
738	      throw new InvalidTransactionBatch('calls must be a non-empty array');
739	    }
740	    if (rawCalls.length > MAX_BATCH_CALLS) {
741	      throw new InvalidTransactionBatch(`too many calls: ${rawCalls.length} > ${MAX_BATCH_CALLS}`);
742	    }
743	    const calls: BatchCall[] = [];
744	    for (const rawCall of rawCalls) {
745	      if (typeof rawCall !== 'object' || rawCall === null) {
746	        throw new InvalidTransactionBatch('each batch call must be an object');
747	      }
748	      const call = rawCall as Record<string, unknown>;
749	      const to = normalizeAddress(call.to as string);
750	      if (to === null || isZeroAddress(to)) {
751	        throw new InvalidTransactionBatch('invalid or zero recipient address in batch call');
752	      }
753	      const value = toBigInt(call.value, InvalidTransactionBatch, 'value');
754	      if (!isNonNegativeInteger(value)) {
755	        throw new InvalidTransactionBatch('batch call value out of range');
756	      }
757	      if (!(call.data instanceof Uint8Array)) {
758	        throw new InvalidTransactionBatch('batch call data must be a Uint8Array');
759	      }
760	      // 复制一份，避免入队后调用方再改动同一缓冲区影响任务内容/摘要
761	      calls.push({ to, value, data: Buffer.from(call.data) });
762	    }
763	    return calls;
764	  }
765	
766	  // ---------- 分阶段审批内部辅助 ----------
767	
768	  private getApprovalRecord(approvalId: string): ApprovalRecord {
769	    const record = typeof approvalId === 'string' ? this.approvals.get(approvalId) : undefined;
770	    if (record === undefined) throw new ApprovalNotFoundError(`approval not found: ${String(approvalId)}`);
771	    return record;
772	  }
773	
774	  /** 已提交 / 已过期 / 版本漂移的审批不可再加签或提交（过期优先于版本冲突） */
775	  private assertApprovalActive(record: ApprovalRecord): void {
776	    if (record.submitted) throw new ApprovalAlreadySubmittedError(`approval ${record.id} already submitted`);
777	    if (record.deadline < this.now()) {
778	      throw new ApprovalExpiredError(`approval deadline ${record.deadline} already passed`);
779	    }
780	    if (record.version !== this.version) {
781	      throw new ApprovalPolicyConflictError(
782	        `policy version drifted: approval bound ${record.version}, current ${this.version}`,
783	      );
784	    }
785	  }
786	
787	  /** 派生状态：submitted > expired > conflicted > ready > collecting */
788	  private approvalStatus(record: ApprovalRecord): ApprovalStatus {
789	    if (record.submitted) return 'submitted';
790	    if (record.deadline < this.now()) return 'expired';
791	    if (record.version !== this.version) return 'conflicted';
792	    return BigInt(record.signers.length) >= record.confirmations ? 'ready' : 'collecting';
793	  }
794	
795	  private approvalSnapshot(record: ApprovalRecord): TransactionApproval {
796	    return {
797	      id: record.id,
798	      digest: record.digest.toString('hex'),
799	      version: record.version,
800	      confirmations: record.confirmations,
801	      signers: [...record.signers],
802	      status: this.approvalStatus(record),
803	    };
804	  }
805	
806	  /** 按“当前策略”的所有者集合与确认数校验签名收集 */
807	  private verifyThresholdSignatures(
808	    digest: Uint8Array,
809	    signatures: readonly Uint8Array[],
810	    Invalid: new (msg: string) => Error,
811	  ): void {
812	    if (!Array.isArray(signatures)) {
813	      throw new Invalid('signatures must be an array');
814	    }
815	    if (signatures.length === 0) throw new Invalid('missing signatures');
816	
817	    const signedBy = new Set<Address>();
818	    for (const sig of signatures) {
819	      if (!(sig instanceof Uint8Array) || sig.length !== 65) {
820	        throw new Invalid('each signature must be a 65-byte r||s||v blob');
821	      }
822	      const signer = recoverAddress(digest, Uint8Array.from(sig));
823	      if (signer === null) throw new Invalid('malformed or non-canonical signature');
824	      if (!this.ownerSet.has(signer)) {
825	        // 非所有者签名：既可能是伪造，也可能是签名载荷与提交内容不匹配
826	        throw new Invalid('signature does not match payload or signer is not an owner');
827	      }
828	      signedBy.add(signer); // 地址去重：同一所有者多签只计一次
829	    }
830	    if (BigInt(signedBy.size) < this.confirmations) {
831	      throw new Invalid(
832	        `threshold not met: need ${this.confirmations} distinct owners, got ${signedBy.size}`,
833	      );
834	    }
835	  }
836	
837	  /** 队列执行器回调：定义各类任务的生效语义 */
838	  private applyTask(task: WalletTask): unknown {
839	    const p = task.payload;
840	    if (p.kind === 'transaction') {
841	      // 普通交易既有执行结果：一个可观察的执行产物；不触碰策略状态。
842	      // 截止时间只在提交阶段核对（RequestExpired），不作为执行闸门，以保持既有执行结果不变。
843	      return {
844	        kind: 'transfer',
845	        to: p.to,
846	        value: p.value,
847	        data: Buffer.from(p.data).toString('hex'),
848	      };
849	    }
850	
851	    if (p.kind === 'transaction-batch') {
852	      // 原子批量：执行器一次性产出整批回执。调用方（队列）在本回调正常返回后才写入
853	      // executed 终态；本回调抛出则整批进入 failed，不产生部分执行回执。
854	      // 截止时间同样不是执行闸门，与单笔普通交易保持一致。
855	      return {
856	        kind: 'transfer-batch',
857	        calls: p.calls.map((call) => ({
858	          to: call.to,
859	          value: call.value,
860	          data: Buffer.from(call.data).toString('hex'),
861	        })),
862	      };
863	    }
864	
865	    // 策略变更：仅当绑定版本仍等于当前版本时生效
866	    if (p.version !== this.version) {
867	      throw new PolicyConflict(
868	        `policy version drifted: task bound ${p.version}, current ${this.version}`,
869	      );
870	    }
871	    // 所有者集合与确认数同时替换；版本恰好递增一次
872	    this.owners = [...p.newOwners];
873	    this.ownerSet.clear();
874	    for (const o of this.owners) this.ownerSet.add(o);
875	    this.confirmations = p.newConfirmations;
876	    this.version += 1n;
877	    return {
878	      kind: 'policy-applied',
879	      version: this.version,
880	      owners: [...this.owners],
881	      confirmations: this.confirmations,
882	    };
883	  }
884	}
885	
886	// ---------- 所有者列表规范化（空/重复/零地址校验） ----------
887	
888	function normalizeOwnerList(
889	  input: readonly string[],
890	  ErrorCtor: typeof InvalidPolicyChange | typeof InvalidTransaction = InvalidPolicyChange,
891	): Address[] {
892	  if (!Array.isArray(input) || input.length === 0) {
893	    throw new ErrorCtor('owners list must be a non-empty array');
894	  }
895	  const out: Address[] = [];
896	  const seen = new Set<Address>();
897	  for (const raw of input) {
898	    const addr = normalizeAddress(raw);
899	    if (addr === null) throw new ErrorCtor(`invalid owner address: ${String(raw)}`);
900	    if (addr === ZERO_ADDRESS || isZeroAddress(addr)) {
901	      throw new ErrorCtor('zero address is not allowed as owner');
902	    }
903	    if (seen.has(addr)) throw new ErrorCtor(`duplicate owner: ${addr}`);
904	    seen.add(addr);
905	    out.push(addr);
906	  }
907	  return out;
908	}
