1	/**
2	 * 规范化编码与签名摘要。
3	 *
4	 * 各类操作使用不同的域分隔标签，签名互不兼容（任一类型的签名都不能用于其他类型）：
5	 *   - 普通交易：         "safe-wallet/tx/v1"
6	 *   - 原子批量交易：     "safe-wallet/tx-batch/v1"
7	 *   - 策略变更：         "safe-wallet/policy-change/v1"
8	 *   - 任务取消：         "safe-wallet/cancel/v1"
9	 *   - 普通交易分阶段审批："safe-wallet/tx-approval/v1"
10	 *
11	 * 编码规则（全部大端）：
12	 *   encBytes(b)  = uint32(len) || b
13	 *   encStr(s)    = uint32(len) || utf8(s)
14	 *   encUint(n)   = n 的定长 32 字节大端表示
15	 *   encList(xs)  = uint32(count) || concat(encBytes(x))
16	 *
17	 * 普通交易载荷不包含策略版本字段（保持既有交易格式不变）；
18	 * 批量交易载荷绑定钱包标识、nonce、截止时间，以及按顺序编码的全部调用
19	 * （每调用固定按“收款地址 || 金额 || data”编码，再以 encList 绑定项数与顺序）；
20	 * 策略变更载荷显式绑定钱包标识、操作标签、当前版本、新所有者、新确认数、nonce、截止时间。
21	 */
22	
23	import { sha256, hexToBytes, type Address } from './crypto.ts';
24	
25	const TAG_TX = 'safe-wallet/tx/v1';
26	const TAG_TX_BATCH = 'safe-wallet/tx-batch/v1';
27	const TAG_POLICY_CHANGE = 'safe-wallet/policy-change/v1';
28	const TAG_CANCEL = 'safe-wallet/cancel/v1';
29	const TAG_TX_APPROVAL = 'safe-wallet/tx-approval/v1';
30	
31	// ---------- 编码原语 ----------
32	
33	export function encBytes(data: Uint8Array): Buffer {
34	  const b = Buffer.from(data);
35	  const out = Buffer.alloc(4 + b.length);
36	  out.writeUInt32BE(b.length, 0);
37	  b.copy(out, 4);
38	  return out;
39	}
40	
41	export function encStr(s: string): Buffer {
42	  return encBytes(Buffer.from(s, 'utf8'));
43	}
44	
45	export function encUint(n: bigint | number): Buffer {
46	  const v = BigInt(n);
47	  if (v < 0n) throw new Error('cannot encode negative integer');
48	  if (v >> 256n !== 0n) throw new Error('integer exceeds 32 bytes');
49	  const out = Buffer.alloc(32);
50	  let x = v;
51	  for (let i = 31; i >= 0; i--) {
52	    out[i] = Number(x & 0xffn);
53	    x >>= 8n;
54	  }
55	  return out;
56	}
57	
58	export function encList(items: Uint8Array[]): Buffer {
59	  const head = Buffer.alloc(4);
60	  head.writeUInt32BE(items.length, 0);
61	  return Buffer.concat([head, ...items.map(encBytes)]);
62	}
63	
64	function digest(tag: string, parts: Buffer[]): Buffer {
65	  return sha256(Buffer.concat([encStr(tag), ...parts]));
66	}
67	
68	// ---------- 请求类型 ----------
69	
70	export interface TransactionRequest {
71	  /** 钱包标识（部署时确定；参与签名绑定，防止跨钱包重放） */
72	  walletId: string;
73	  nonce: bigint;
74	  /** Unix 秒级截止时间（也接受毫秒级大数；语义由调用方约定，引擎按数值比较） */
75	  deadline: bigint;
76	  to: Address;
77	  value: bigint;
78	  data: Uint8Array;
79	}
80	
81	export interface PolicyChangeRequest {
82	  walletId: string;
83	  /** 提交时绑定的当前策略版本 */
84	  version: bigint;
85	  nonce: bigint;
86	  deadline: bigint;
87	  newOwners: Address[];
88	  newConfirmations: bigint;
89	}
90	
91	/** 批量交易中的单次调用：收款地址、金额、附带数据 */
92	export interface BatchTransactionCall {
93	  to: Address;
94	  value: bigint;
95	  data: Uint8Array;
96	}
97	
98	export interface TransactionBatchRequest {
99	  /** 钱包标识（部署时确定；参与签名绑定，防止跨钱包重放） */
100	  walletId: string;
101	  nonce: bigint;
102	  deadline: bigint;
103	  /** 有序调用列表（1..64 项）；顺序参与签名，不得改变 */
104	  calls: BatchTransactionCall[];
105	}
106	
107	export interface CancellationRequest {
108	  walletId: string;
109	  /** 目标任务的签名摘要（hex）：把取消请求绑定到唯一任务，防止改绑其他任务 */
110	  taskDigest: string;
111	  nonce: bigint;
112	  deadline: bigint;
113	}
114	
115	export interface TransactionApprovalRequest {
116	  walletId: string;
117	  /** 创建审批时绑定的当前策略版本 */
118	  version: bigint;
119	  nonce: bigint;
120	  deadline: bigint;
121	  to: Address;
122	  value: bigint;
123	  data: Uint8Array;
124	}
125	
126	function walletIdBytes(walletId: string): Buffer {
127	  // 钱包标识统一按 UTF-8 参与签名绑定（任意字符串均可）
128	  return Buffer.from(walletId, 'utf8');
129	}
