135	/** 普通交易的签名摘要（不含策略版本字段） */
136	export function hashTransaction(req: {
137	  walletId: string;
138	  nonce: bigint | number;
139	  deadline: bigint | number;
140	  to: Address;
141	  value: bigint | number;
