1	/**
2	 * 执行队列：FIFO 排序、仅队首可执行、终态不可逆、执行幂等。
3	 *
4	 * 队列本身不关心任务内容：准入校验由钱包引擎完成；执行语义由执行器回调提供。
5	 * 任务 id 由入队序号与任务摘要派生，保证同一引擎内可复现、可引用。
6	 * 任务状态：queued → executed / failed / cancelled（均为终态，不可逆）。
7	 * 取消不要求任务在队首、不调整队列顺序；执行时越过队首（或连续）的 cancelled 任务。
8	 */
9	
10	import { createHash } from 'node:crypto';
11	import { InvalidQueueStateError, TaskCancellationConflict, TaskNotFoundError } from './errors.ts';
12	
13	export type TaskStatus = 'queued' | 'executed' | 'failed' | 'cancelled';
14	
15	export interface QueueTask<P = unknown> {
16	  id: string;
17	  /** 入队序号，从 0 起严格递增；同时决定执行顺序 */
18	  seq: number;
19	  nonce: bigint;
20	  status: TaskStatus;
21	  submittedAt: bigint;
22	  /** 签名摘要（域分隔），作为队列层面的防重指纹 */
23	  digest: string;
24	  payload: P;
25	  receipt?: ExecutionReceipt;
26	  /** 取消终态的记录：取消时间与取消请求摘要；仅 status === 'cancelled' 时存在 */
27	  cancellation?: CancellationRecord;
28	}
29	
30	export interface CancellationRecord {
31	  cancelledAt: bigint;
32	  /** 取消请求的签名摘要（hex，safe-wallet/cancel/v1 域） */
33	  digest: string;
34	}
35	
36	export interface ExecutionReceipt {
37	  status: Extract<TaskStatus, 'executed' | 'failed'>;
38	  /** 失败时为错误名称（如 PolicyConflict / RequestExpired），成功时为 null */
39	  failureReason: string | null;
40	  failureMessage: string | null;
41	  executedAt: bigint;
42	  /** 成功执行的输出（执行器回调返回） */
43	  result?: unknown;
44	}
45	
46	/**
47	 * 执行器：对队首任务做实际生效处理。
48	 * 抛错 → 任务进入 failed 终态（错误名称写入回执）；正常返回 → executed 终态。
49	 */
50	export type Executor<P> = (task: QueueTask<P>) => unknown;
51	
52	export class ExecutionQueue<P = unknown> {
53	  private readonly tasks: QueueTask<P>[] = [];
54	  private head = 0;
55	  private readonly executor: Executor<P>;
56	
57	  constructor(executor: Executor<P>) {
58	    this.executor = executor;
59	  }
60	
61	  /**
62	   * 入队（FIFO 尾部）。
63	   * digest 是任务内容的唯一承诺：在全部历史任务（含失败终态）上都不得重复。
64	   * 失败任务的 nonce 已被消费，其摘要重现本就会被上层 nonce 防护拦截，这里再兜一层，
65	   * 保证队列层面的严格防重。
66	   */
67	  enqueue(input: { nonce: bigint; digest: string; payload: P; submittedAt: bigint }): QueueTask<P> {
68	    if (this.tasks.some((t) => t.digest === input.digest)) {
69	      throw new InvalidQueueStateError(`duplicate task digest: ${input.digest}`);
70	    }
71	    const seq = this.tasks.length;
72	    const task: QueueTask<P> = {
73	      id: createHash('sha256').update(`${seq}:${input.digest}`).digest('hex').slice(0, 16),
74	      seq,
75	      nonce: input.nonce,
76	      status: 'queued',
77	      submittedAt: input.submittedAt,
78	      digest: input.digest,
79	      payload: input.payload,
80	    };
81	    this.tasks.push(task);
82	    return task;
83	  }
84	
85	  /** 队首任务；队列空或队首已终态时为 null */
86	  peekHead(): QueueTask<P> | null {
87	    return this.head < this.tasks.length ? (this.tasks[this.head] ?? null) : null;
88	  }
89	
90	  /**
91	   * 执行指定任务。
92	   * - 仅队首可执行（保证排序/nonce 语义）；队首的已取消任务视为已越过，不计入排序；
93	   * - 终态任务（含 cancelled）重复调用直接返回既有状态，不重复生效（幂等）；
94	   * - 不存在的 id 抛 TaskNotFoundError；非队首的待执行任务抛 InvalidQueueStateError。
95	   */
96	  execute(id: string, now: bigint): QueueTask<P> {
97	    const task = this.tasks.find((t) => t.id === id);
98	    if (task === undefined) throw new TaskNotFoundError(`task not found: ${id}`);
99	    if (task.status !== 'queued') return task; // 幂等：回放终态（executed/failed/cancelled）
100	    this.advanceHead();
101	    if (task.seq !== this.head) {
102	      throw new InvalidQueueStateError(`task ${id} is not at queue head`);
103	    }
104	
105	    try {
106	      const result = this.executor(task);
107	      task.receipt = { status: 'executed', failureReason: null, failureMessage: null, executedAt: now, result };
108	      task.status = 'executed';
109	    } catch (err) {
110	      const e = err as Error;
111	      task.receipt = { status: 'failed', failureReason: e.name, failureMessage: e.message, executedAt: now };
112	      task.status = 'failed';
113	    }
114	    this.head += 1;
115	    return task;
116	  }
117	
118	  /**
119	   * 取消指定任务（不要求在队首，也不调整队列顺序）。
120	   * 目标任务必须由 queued 进入 cancelled 终态：保留原 payload/digest/nonce，
121	   * 记录取消时间与取消摘要；不存在的 id 抛 TaskNotFoundError，
122	   * 已终态（executed/failed/cancelled）抛 TaskCancellationConflict。
123	   */
124	  cancel(id: string, now: bigint, digest: string): QueueTask<P> {
125	    const task = this.tasks.find((t) => t.id === id);
126	    if (task === undefined) throw new TaskNotFoundError(`task not found: ${id}`);
127	    if (task.status !== 'queued') {
128	      throw new TaskCancellationConflict(`task ${id} is already ${task.status}`);
129	    }
130	    task.status = 'cancelled';
131	    task.cancellation = { cancelledAt: now, digest };
132	    this.advanceHead();
133	    return task;
134	  }
135	
136	  /** 越过队首（或连续）的终态任务，使 head 指向首个 queued 任务（或排空） */
137	  private advanceHead(): void {
138	    while (this.head < this.tasks.length && this.tasks[this.head]!.status !== 'queued') {
139	      this.head += 1;
140	    }
141	  }
142	
143	  /** 执行首个 queued 任务（越过队首或连续的 cancelled 任务）；剩余全是终态时返回 null */
144	  executeNext(now: bigint): QueueTask<P> | null {
145	    this.advanceHead();
146	    const head = this.peekHead();
147	    if (head === null) return null;
148	    return this.execute(head.id, now);
149	  }
150	
151	  getTask(id: string): QueueTask<P> | null {
152	    return this.tasks.find((t) => t.id === id) ?? null;
153	  }
154	
155	  /** 队列快照（按入队顺序），任务在执行前后均可见 */
156	  listTasks(): readonly QueueTask<P>[] {
157	    return this.tasks;
158	  }
159	
160	  get size(): number {
161	    return this.tasks.length;
162	  }
163	}
164

