49	// ---------- secp256k1 曲线参数 ----------
50	
51	const P = 2n ** 256n - 2n ** 32n - 977n;
52	const N = BigInt('0xfffffffffffffffffffffffffffffffebaaedce6af48a03bbfd25e8cd0364141');
53	const HALF_N = N >> 1n;
54	const Gx = BigInt('55066263022277343669578718895168534326250603453777594175500187360389116729240');
55	const Gy = BigInt('32670510020758816978083085130507043184471273380659243275938904335757337482424');
