161	  /** 65 字节未压缩公钥 0x04 || X || Y */
162	  publicKey: Buffer;
163	  address: Address;
164	}
165	
166	export function publicKeyFromScalar(d: bigint): Buffer {
167	  if (d <= 0n || d >= N) throw new Error('private scalar out of range');
