217	// ---------- 公钥恢复 ----------
218	
219	function decompressPoint(x: bigint, oddY: boolean): { x: bigint; y: bigint } | null {
220	  if (x >= P) return null;
221	  const alpha = mod(x * x * x + 7n);
222	  // p ≡ 3 (mod 4)
223	  let y = modPow(alpha, (P + 1n) / 4n, P);
224	  if (mod(y * y) !== alpha) return null;
225	  if ((y & 1n) === (oddY ? 0n : 1n)) y = P - y;
226	  return { x, y };
227	}
