test('策略审批任务与直接提交任务共用 FIFO：按入队顺序执行', () => {
  const { wallet, ownerActors } = setup();
  // nonce 0：直接提交一笔普通交易（不改变策略版本）
  const txSigs = signTransaction(ownerActors.slice(0, 2), {
